        response.send(holidays.list(sheetId));
    }
}
package net.officefloor.hq.app.holiday;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds the holiday; the due-by dates already fixed stay as they are. */
public class SaveHoliday {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidHoliday holiday, Holidays holidays, Audit audit,
            ObjectResponse<List<String>> response) {
        holidays.add(sheetId, holiday.date());
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + holiday.user() + " date=" + holiday.date());
        response.send(holidays.list(sheetId));
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHoliday {

    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody HolidayRequest request, Out<ValidHoliday> body,
            Settings settings, Holidays holidays) throws InvalidHolidayException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String raw = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = LocalDate.parse(raw, DATE);
        } catch (DateTimeParseException e) {
            throw new InvalidHolidayException("The holiday must be a date (YYYY-MM-DD)");
        }
        if (holidays.contains(sheetId, date)) {
            throw new InvalidHolidayException("The date is already a holiday");
        }
        body.set(new ValidHoliday(date, request.user()));
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;

/** A holiday that passed validation: a date not yet on the sheet's list. */
public record ValidHoliday(LocalDate date, String user) {
}
