import { asString, useSearchParam } from '../../url/useSearchParam';
import { GRADES, gradeOn, type Person } from '../people/usePeople';
import { STATUSES } from '../people/useSheetFigures';
import { usePeriodDueTotal } from '../periods/usePeriodDueTotal';
import { usePeriods } from '../periods/usePeriods';
import { formatCents } from '../rates/due';

// The sheet at a glance, worked from the same figures the lists show. Per grade: how many people
// are on it today (retired people left out), their due-totals added up (skipping n/a) and how many
// of them are active. Per period: its due-total, as the period list shows it. Per status: how many claims have it.
export function SummaryPanel({
  people,
  today,
  totalOf,
  isActive,
  statusCount,
}: {
  people: Person[];
  today: string | undefined;
  totalOf: (person: Person) => bigint | null;
  isActive: (person: Person) => boolean;
  statusCount: (status: (typeof STATUSES)[number]) => number;
}) {
  const [sheet] = useSearchParam('sheet', asString);
  const periods = usePeriods(sheet);
  const periodDueTotal = usePeriodDueTotal(sheet);
  const current = people.filter((p) => !p.retired);
  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => gradeOn(p, today) === g);
            const due = onGrade.reduce((sum, p) => sum + (totalOf(p) ?? 0n), 0n);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{formatCents(due)}</td>
                <td data-testid={`summary-grade-${g}-active`}>{onGrade.filter(isActive).length}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{formatCents(periodDueTotal(p))}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { holidaysKey, useHolidays } from './useHolidays';

// The sheet's holidays and the form that adds one (a date already on the list is refused). A claim's
// due-by fixed at creation that falls on a holiday moves to the next day that is not one.
export function HolidayPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const holidays = useHolidays(sheet);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { date: string }) =>
      postJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { ...body, user }),
    onSuccess: (saved) => {
      setDate('');
      queryClient.setQueryData(holidaysKey(sheet), saved);
    },
  });
  return (
    <>
      <ul data-testid="holiday-list">
        {holidays.map((h) => (
          <li key={h} data-testid={`holiday-row-${h}`}>{h}</li>
        ))}
      </ul>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ date: date.trim() });
          });
        }}
      >
        <input
          data-testid="holiday-date"
          value={date}
          placeholder="Holiday (YYYY-MM-DD)"
          onChange={(e) => {
            setDate(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        {add.isError && <span data-testid="holiday-error" role="alert"> Could not add the holiday: it must be a date (YYYY-MM-DD) not already on the list.</span>}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export const holidaysKey = (sheet: string) => ['sheet', sheet, 'holidays'] as const;

/** The sheet's holidays (YYYY-MM-DD), earliest first. */
export function useHolidays(sheet: string): string[] {
  const { data } = useQuery({
    queryKey: holidaysKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
